//! 📐️ Controlled authored CAD layers, blocks and every entity variant.
use crate::standards::v1::subsets::base::schema::geometry::{SemioPoint2};
use crate::standards::v1::subsets::cad::schema::snapshot::{SemioCadSnapshot,CadLayer,CadBlock,CadEntityRecord,CadEntity,STDIO_SEMIOCAD_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(crate) fn decode(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>,native_control:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<SemioCadSnapshot,ValueError>{
 let limits=control.limits();crate::standards::v1::subsets::cad::io::sqlite::snapshot::admit_layout(limits)?;
 let size=match payload{store::io::IoPayload::Binary(value)=>value.len(),store::io::IoPayload::Text(value)=>value.len()};if size>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio CAD native input exceeds file limit"))}
 control.allocation_stage_native(store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative,|remaining,checkpoint|{
  let native_before=native_control.owned_bytes();let Some(allowance)=native_before.checked_add(remaining) else{return (Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"native snapshot allowance overflow")),0)};let result=native_control.scoped_maximum(allowance,|native_control|{
  let result=(||->Result<SemioCadSnapshot,ValueError>{let result=match payload{
   store::io::IoPayload::Binary(value)=>{let body=store::semio_format::unwrap_binary_controlled(value,STDIO_SEMIOCAD_DOCUMENT_SCHEMA,store::semio_format::Component::Pack,1,native_control)?;binary(body,native_control,limits)?},
   store::io::IoPayload::Text(value)=>{let body=store::semio_format::split_text_preamble_controlled(value,STDIO_SEMIOCAD_DOCUMENT_SCHEMA,store::semio_format::Component::Dsl,1,native_control).map_err(store::semio_format::SemioError::into_value_error)?;document(body,native_control,limits)?}
  };let result=native::Owned::new(result);native_control.checkpoint()?;Ok(result.take())})();result});(result,native_control.owned_bytes().saturating_sub(native_before))
 })?
}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,ValueError>{reader.read_f64_le().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))}
fn point(reader:&mut store::ByteReader<'_>)->Result<SemioPoint2,ValueError>{Ok(SemioPoint2{x:f64(reader)?,y:f64(reader)?})}
fn boolean(value:u8)->Result<bool,ValueError>{match value{0=>Ok(false),1=>Ok(true),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native CAD boolean"))}}
fn entity_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<CadEntity,ValueError>{
 native::entities(entities,1,limits)?;Ok(match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{
 0=>CadEntity::Line{a:point(reader)?,b:point(reader)?},1=>CadEntity::Arc{center:point(reader)?,radius:f64(reader)?,start_angle:f64(reader)?,end_angle:f64(reader)?},2=>CadEntity::Circle{center:point(reader)?,radius:f64(reader)?},3=>CadEntity::Ellipse{center:point(reader)?,major_axis_end:point(reader)?,ratio:f64(reader)?,start_param:f64(reader)?,end_param:f64(reader)?},
 4=>{let vertices=native::binary_list(reader,control,limits,entities,|reader,_,_|point(reader))?;let mut owner=native::Owned::new(CadEntity::Polyline{vertices,closed:false});if let CadEntity::Polyline{closed,..}=owner.get_mut(){*closed=boolean(reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?)?;}owner.take()},
 5=>CadEntity::Text{position:point(reader)?,height:f64(reader)?,rotation:f64(reader)?,content:native::text(reader,control)?},6=>{let block_name=native::text(reader,control)?;let mut owner=native::Owned::new(CadEntity::Insert{block_name,insertion_point:SemioPoint2{x:0.0,y:0.0},scale:SemioPoint2{x:0.0,y:0.0},rotation:0.0});if let CadEntity::Insert{insertion_point,scale,rotation,..}=owner.get_mut(){*insertion_point=point(reader)?;*scale=point(reader)?;*rotation=f64(reader)?;}owner.take()},7=>CadEntity::Solid{p1:point(reader)?,p2:point(reader)?,p3:point(reader)?,p4:point(reader)?},8=>CadEntity::Dimension{def_point:point(reader)?,text_position:point(reader)?,measurement:f64(reader)?,text:native::text(reader,control)?},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native CAD entity"))})
}
fn record_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<CadEntityRecord,ValueError>{let handle=native::text(reader,control)?;let mut owner=native::Owned::new(CadEntityRecord{handle,layer:String::new(),entity:CadEntity::default()});owner.get_mut().layer=native::text(reader,control)?;owner.get_mut().entity=entity_binary(reader,control,limits,entities)?;Ok(owner.take())}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioCadSnapshot,ValueError>{crate::standards::v1::subsets::cad::io::sqlite::snapshot::admit_binary(body,control,limits)?;
 let mut entities=0;native::entities(&mut entities,1,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Semio CAD native format"))}let schema=native::text(&mut reader,control)?;let mut owner=native::Owned::new(SemioCadSnapshot{schema,layers:Vec::new(),blocks:Vec::new(),entities:Vec::new()});
 owner.get_mut().layers=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|{let name=native::text(reader,control)?;let mut owner=native::Owned::new(CadLayer{name,color_index:0,line_type:String::new(),visible:false});let bits=reader.read_varint_u64().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?;let color_index=bits as i32;if color_index as u64!=bits{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native signed32 layer color"))}owner.get_mut().color_index=color_index;owner.get_mut().line_type=native::text(reader,control)?;owner.get_mut().visible=boolean(reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?)?;Ok(owner.take())})?;
 owner.get_mut().blocks=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let name=native::text(reader,control)?;let mut owner=native::Owned::new(CadBlock{name,base_point:SemioPoint2{x:0.0,y:0.0},entities:Vec::new()});owner.get_mut().base_point=point(reader)?;owner.get_mut().entities=native::binary_list(reader,control,limits,entities,|reader,control,entities|record_binary(reader,control,limits,entities))?;Ok(owner.take())})?;
 owner.get_mut().entities=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|record_binary(reader,control,limits,entities))?;if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Semio CAD native trailing bytes"))}Ok(owner.take())
}
fn point_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioPoint2,ValueError>{let[x,y]=native::record(value,control)?;Ok(SemioPoint2{x:native::float(x,control)?,y:native::float(y,control)?})}
fn bool_text(value:&str)->Result<bool,ValueError>{match value{"0"=>Ok(false),"1"=>Ok(true),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native CAD boolean"))}}
fn entity_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<CadEntity,ValueError>{
 native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Semio native CAD entity tag missing"))?;Ok(match tag{
 "L"=>{let[a,b]=native::record(value,control)?;CadEntity::Line{a:point_text(a,control)?,b:point_text(b,control)?}},
 "A"=>{let[center,radius,start_angle,end_angle]=native::record(value,control)?;CadEntity::Arc{center:point_text(center,control)?,radius:native::float(radius,control)?,start_angle:native::float(start_angle,control)?,end_angle:native::float(end_angle,control)?}},
 "C"=>{let[center,radius]=native::record(value,control)?;CadEntity::Circle{center:point_text(center,control)?,radius:native::float(radius,control)?}},
 "E"=>{let[center,major_axis_end,ratio,start_param,end_param]=native::record(value,control)?;CadEntity::Ellipse{center:point_text(center,control)?,major_axis_end:point_text(major_axis_end,control)?,ratio:native::float(ratio,control)?,start_param:native::float(start_param,control)?,end_param:native::float(end_param,control)?}},
 "P"=>{let[vertices,closed]=native::record(value,control)?;let vertices=native::text_list(vertices,control,limits,entities,|value,control,_|point_text(value,control))?;let mut owner=native::Owned::new(CadEntity::Polyline{vertices,closed:false});if let CadEntity::Polyline{closed:value,..}=owner.get_mut(){*value=bool_text(closed)?;}owner.take()},
 "T"=>{let[position,height,rotation,content]=native::record(value,control)?;CadEntity::Text{position:point_text(position,control)?,height:native::float(height,control)?,rotation:native::float(rotation,control)?,content:native::hex_text(content,control)?}},
 "I"=>{let[block_name,insertion_point,scale,rotation]=native::record(value,control)?;let block_name=native::hex_text(block_name,control)?;let mut owner=native::Owned::new(CadEntity::Insert{block_name,insertion_point:SemioPoint2{x:0.0,y:0.0},scale:SemioPoint2{x:0.0,y:0.0},rotation:0.0});if let CadEntity::Insert{insertion_point:value,scale:extent,rotation:angle,..}=owner.get_mut(){*value=point_text(insertion_point,control)?;*extent=point_text(scale,control)?;*angle=native::float(rotation,control)?;}owner.take()},
 "S"=>{let[p1,p2,p3,p4]=native::record(value,control)?;CadEntity::Solid{p1:point_text(p1,control)?,p2:point_text(p2,control)?,p3:point_text(p3,control)?,p4:point_text(p4,control)?}},
 "D"=>{let[def_point,text_position,measurement,text]=native::record(value,control)?;CadEntity::Dimension{def_point:point_text(def_point,control)?,text_position:point_text(text_position,control)?,measurement:native::float(measurement,control)?,text:native::hex_text(text,control)?}},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native CAD entity"))})
}
fn record_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<CadEntityRecord,ValueError>{let[handle,layer,value]=native::record(value,control)?;let handle=native::hex_text(handle,control)?;let mut owner=native::Owned::new(CadEntityRecord{handle,layer:String::new(),entity:CadEntity::default()});owner.get_mut().layer=native::hex_text(layer,control)?;owner.get_mut().entity=entity_text(value,control,limits,entities)?;Ok(owner.take())}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioCadSnapshot,ValueError>{crate::standards::v1::subsets::cad::io::sqlite::snapshot::admit_document(body,control,limits)?;
 let mut entities=0;native::entities(&mut entities,1,limits)?;let fields=native::fields(body,["schema","layers","blocks","entities"],control)?;let schema=native::hex_text(fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Semio CAD native schema missing"))?,control)?;let mut owner=native::Owned::new(SemioCadSnapshot{schema,layers:Vec::new(),blocks:Vec::new(),entities:Vec::new()});
 owner.get_mut().layers=native::text_list(fields[1].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[name,color_index,line_type,visible]=native::record(value,control)?;let name=native::hex_text(name,control)?;let mut owner=native::Owned::new(CadLayer{name,color_index:0,line_type:String::new(),visible:false});let color_index=control.scoped_stage(|control|{control.begin_stage(color_index.len())?;for _ in color_index.bytes(){control.step()?;}color_index.parse::<i32>().map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native signed32 layer color"))})?;owner.get_mut().color_index=color_index;owner.get_mut().line_type=native::hex_text(line_type,control)?;owner.get_mut().visible=bool_text(visible)?;Ok(owner.take())})?;
 owner.get_mut().blocks=native::text_list(fields[2].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{let[name,base_point,records]=native::record(value,control)?;let name=native::hex_text(name,control)?;let mut owner=native::Owned::new(CadBlock{name,base_point:SemioPoint2{x:0.0,y:0.0},entities:Vec::new()});owner.get_mut().base_point=point_text(base_point,control)?;owner.get_mut().entities=native::text_list(records,control,limits,entities,|value,control,entities|record_text(value,control,limits,entities))?;Ok(owner.take())})?;
 owner.get_mut().entities=native::text_list(fields[3].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|record_text(value,control,limits,entities))?;Ok(owner.take())
}
/// 🕳️ The empty typed root every native prefix starts from.
pub(crate) fn empty()->crate::standards::v1::subsets::cad::schema::snapshot::SemioCadSnapshot{crate::standards::v1::subsets::cad::schema::snapshot::SemioCadSnapshot{schema:String::new(),layers:Vec::new(),blocks:Vec::new(),entities:Vec::new()}}
